-- Append-only simulation catalogs. Existing loop policies, running attempts and
-- earned cooldowns remain unchanged; new scenarios explicitly apply a strategy.
CREATE TABLE mx_device.rule_definitions (
 id text PRIMARY KEY, mode text NOT NULL CHECK(mode='sim'), code text NOT NULL,
 version integer NOT NULL CHECK(version>0), document jsonb NOT NULL,
 UNIQUE(mode,code,version),
 CHECK(document->>'id'=id AND document->>'mode'=mode AND document->>'code'=code AND (document->>'version')::integer=version)
);
CREATE INDEX rule_definitions_latest ON mx_device.rule_definitions(mode,code,version DESC);
INSERT INTO mx_device.rule_definitions VALUES ('sim:placement.adaptive:1','sim','placement.adaptive',1,'{"id":"sim:placement.adaptive:1","mode":"sim","code":"placement.adaptive","name":"均衡分配 · 自适应","description":"空闲设备超过 50% 时倾向分散；否则优先复用同 App，额外等待不超过 3 秒。","kind":"placement","config":{"strategy":"adaptive","idleSpreadThresholdPct":50,"maxAffinityDelayMs":3000},"version":1,"archived":false,"createdAt":0}'::jsonb);
INSERT INTO mx_device.rule_definitions VALUES ('sim:placement.spread:1','sim','placement.spread',1,'{"id":"sim:placement.spread:1","mode":"sim","code":"placement.spread","name":"空闲设备优先","description":"更重视尽快开始任务，适合资源充裕的演练。","kind":"placement","config":{"strategy":"spread","idleSpreadThresholdPct":50,"maxAffinityDelayMs":3000},"version":1,"archived":false,"createdAt":0}'::jsonb);
INSERT INTO mx_device.rule_definitions VALUES ('sim:placement.affinity:1','sim','placement.affinity',1,'{"id":"sim:placement.affinity:1","mode":"sim","code":"placement.affinity","name":"同 App 亲和优先","description":"优先复用同 App 上下文，仍受队列、冷却和等待预算限制。","kind":"placement","config":{"strategy":"affinity","idleSpreadThresholdPct":50,"maxAffinityDelayMs":3000},"version":1,"archived":false,"createdAt":0}'::jsonb);
INSERT INTO mx_device.rule_definitions VALUES ('sim:queue.bounded:1','sim','queue.bounded',1,'{"id":"sim:queue.bounded:1","mode":"sim","code":"queue.bounded","name":"有界候选队列","description":"预计排队超过 30 秒时保留在中心等待；每机最多 100 个候选任务，15 秒短任务阈值。","kind":"queue","config":{"maxQueueWaitMs":30000,"maxQueuePerDevice":100,"shortTaskMs":15000},"version":1,"archived":false,"createdAt":0}'::jsonb);
INSERT INTO mx_device.rule_definitions VALUES ('sim:budget.default:1','sim','budget.default',1,'{"id":"sim:budget.default:1","mode":"sim","code":"budget.default","name":"App 默认运行预算","description":"60 秒窗口，最多 3 个任务或 60 秒服务时间，达到预算后休息 5 秒。","kind":"app-budget","config":{"windowMs":60000,"maxRuns":3,"maxServiceMs":60000,"cooldownMs":5000},"version":1,"archived":false,"createdAt":0}'::jsonb);
INSERT INTO mx_device.rule_definitions VALUES ('sim:budget.pdd:1','sim','budget.pdd',1,'{"id":"sim:budget.pdd:1","mode":"sim","code":"budget.pdd","name":"拼多多预算示例","description":"模拟参考：最多 2 个任务后休息 8 秒；不代表真实平台安全限额。","kind":"app-override","config":{"appId":"pdd","policy":{"windowMs":60000,"maxRuns":2,"maxServiceMs":60000,"cooldownMs":8000}},"version":1,"archived":false,"createdAt":0}'::jsonb);

CREATE TABLE mx_device.strategy_definitions (
 id text PRIMARY KEY, mode text NOT NULL CHECK(mode='sim'), code text NOT NULL,
 version integer NOT NULL CHECK(version>0), document jsonb NOT NULL,
 UNIQUE(mode,code,version),
 CHECK(document->>'id'=id AND document->>'mode'=mode AND document->>'code'=code AND (document->>'version')::integer=version)
);
CREATE INDEX strategy_definitions_latest ON mx_device.strategy_definitions(mode,code,version DESC);
INSERT INTO mx_device.strategy_definitions VALUES ('sim:pool.balanced:1','sim','pool.balanced',1,'{"id":"sim:pool.balanced:1","mode":"sim","code":"pool.balanced","name":"均衡自适应","description":"推荐起点：资源充裕时分散，资源忙碌时复用同 App；具体效果需用场景对照验证。","version":1,"archived":false,"recommended":true,"rules":[{"code":"placement.adaptive","version":1,"definition":{"id":"sim:placement.adaptive:1","mode":"sim","code":"placement.adaptive","name":"均衡分配 · 自适应","description":"空闲设备超过 50% 时倾向分散；否则优先复用同 App，额外等待不超过 3 秒。","kind":"placement","config":{"strategy":"adaptive","idleSpreadThresholdPct":50,"maxAffinityDelayMs":3000},"version":1,"archived":false,"createdAt":0}},{"code":"queue.bounded","version":1,"definition":{"id":"sim:queue.bounded:1","mode":"sim","code":"queue.bounded","name":"有界候选队列","description":"预计排队超过 30 秒时保留在中心等待；每机最多 100 个候选任务，15 秒短任务阈值。","kind":"queue","config":{"maxQueueWaitMs":30000,"maxQueuePerDevice":100,"shortTaskMs":15000},"version":1,"archived":false,"createdAt":0}},{"code":"budget.default","version":1,"definition":{"id":"sim:budget.default:1","mode":"sim","code":"budget.default","name":"App 默认运行预算","description":"60 秒窗口，最多 3 个任务或 60 秒服务时间，达到预算后休息 5 秒。","kind":"app-budget","config":{"windowMs":60000,"maxRuns":3,"maxServiceMs":60000,"cooldownMs":5000},"version":1,"archived":false,"createdAt":0}}],"policy":{"version":1,"enabled":true,"strategy":"adaptive","idleSpreadThresholdPct":50,"maxAffinityDelayMs":3000,"maxQueueWaitMs":30000,"maxQueuePerDevice":100,"shortTaskMs":15000,"appDefaults":{"windowMs":60000,"maxRuns":3,"maxServiceMs":60000,"cooldownMs":5000},"appPolicies":{}},"createdAt":0}'::jsonb);
INSERT INTO mx_device.strategy_definitions VALUES ('sim:pool.spread:1','sim','pool.spread',1,'{"id":"sim:pool.spread:1","mode":"sim","code":"pool.spread","name":"空闲分散","description":"优先启动空闲设备，便于观察延迟与上下文切换成本的取舍。","version":1,"archived":false,"recommended":false,"rules":[{"code":"placement.spread","version":1,"definition":{"id":"sim:placement.spread:1","mode":"sim","code":"placement.spread","name":"空闲设备优先","description":"更重视尽快开始任务，适合资源充裕的演练。","kind":"placement","config":{"strategy":"spread","idleSpreadThresholdPct":50,"maxAffinityDelayMs":3000},"version":1,"archived":false,"createdAt":0}},{"code":"queue.bounded","version":1,"definition":{"id":"sim:queue.bounded:1","mode":"sim","code":"queue.bounded","name":"有界候选队列","description":"预计排队超过 30 秒时保留在中心等待；每机最多 100 个候选任务，15 秒短任务阈值。","kind":"queue","config":{"maxQueueWaitMs":30000,"maxQueuePerDevice":100,"shortTaskMs":15000},"version":1,"archived":false,"createdAt":0}},{"code":"budget.default","version":1,"definition":{"id":"sim:budget.default:1","mode":"sim","code":"budget.default","name":"App 默认运行预算","description":"60 秒窗口，最多 3 个任务或 60 秒服务时间，达到预算后休息 5 秒。","kind":"app-budget","config":{"windowMs":60000,"maxRuns":3,"maxServiceMs":60000,"cooldownMs":5000},"version":1,"archived":false,"createdAt":0}}],"policy":{"version":1,"enabled":true,"strategy":"spread","idleSpreadThresholdPct":50,"maxAffinityDelayMs":3000,"maxQueueWaitMs":30000,"maxQueuePerDevice":100,"shortTaskMs":15000,"appDefaults":{"windowMs":60000,"maxRuns":3,"maxServiceMs":60000,"cooldownMs":5000},"appPolicies":{}},"createdAt":0}'::jsonb);
INSERT INTO mx_device.strategy_definitions VALUES ('sim:pool.affinity:1','sim','pool.affinity',1,'{"id":"sim:pool.affinity:1","mode":"sim","code":"pool.affinity","name":"亲和聚合","description":"优先同 App 排队执行；聚合指设备与上下文复用，不会合并任务数据或完成回执。","version":1,"archived":false,"recommended":false,"rules":[{"code":"placement.affinity","version":1,"definition":{"id":"sim:placement.affinity:1","mode":"sim","code":"placement.affinity","name":"同 App 亲和优先","description":"优先复用同 App 上下文，仍受队列、冷却和等待预算限制。","kind":"placement","config":{"strategy":"affinity","idleSpreadThresholdPct":50,"maxAffinityDelayMs":3000},"version":1,"archived":false,"createdAt":0}},{"code":"queue.bounded","version":1,"definition":{"id":"sim:queue.bounded:1","mode":"sim","code":"queue.bounded","name":"有界候选队列","description":"预计排队超过 30 秒时保留在中心等待；每机最多 100 个候选任务，15 秒短任务阈值。","kind":"queue","config":{"maxQueueWaitMs":30000,"maxQueuePerDevice":100,"shortTaskMs":15000},"version":1,"archived":false,"createdAt":0}},{"code":"budget.default","version":1,"definition":{"id":"sim:budget.default:1","mode":"sim","code":"budget.default","name":"App 默认运行预算","description":"60 秒窗口，最多 3 个任务或 60 秒服务时间，达到预算后休息 5 秒。","kind":"app-budget","config":{"windowMs":60000,"maxRuns":3,"maxServiceMs":60000,"cooldownMs":5000},"version":1,"archived":false,"createdAt":0}}],"policy":{"version":1,"enabled":true,"strategy":"affinity","idleSpreadThresholdPct":50,"maxAffinityDelayMs":3000,"maxQueueWaitMs":30000,"maxQueuePerDevice":100,"shortTaskMs":15000,"appDefaults":{"windowMs":60000,"maxRuns":3,"maxServiceMs":60000,"cooldownMs":5000},"appPolicies":{}},"createdAt":0}'::jsonb);

